const crypto = require('node:crypto');

function b64url(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64url');
}

// 简化版 HS256 JWT 签发
function signJwt(payload, secret) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const data = b64url(header) + '.' + b64url(payload);
  const signature = crypto.createHmac('sha256', secret).update(data).digest('base64url');
  return data + '.' + signature;
}

// 验签：白名单算法 + 恒定时间比较，拒绝 alg=none
function verifyJwt(token, secret) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('JWT 结构非法');
  const h = parts[0], p = parts[1], s = parts[2];
  const header = JSON.parse(Buffer.from(h, 'base64url').toString());
  if (header.alg !== 'HS256') throw new Error('不支持的算法: ' + header.alg);
  const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest('base64url');
  const a = Buffer.from(s);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('签名无效');
  return JSON.parse(Buffer.from(p, 'base64url').toString());
}

const secret = 'a-strong-secret-key';
const token = signJwt({ sub: 'u123', role: 'user' }, secret);
console.log('JWT:', token);
console.log('payload 可被任何人解码:', JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString()));
console.log('正确密钥验签:', verifyJwt(token, secret));
try { verifyJwt(token, 'wrong-secret'); } catch (e) { console.log('错误密钥:', e.message); }

const tp = token.split('.');
const forged = tp[0] + '.' + b64url({ sub: 'u123', role: 'admin' }) + '.' + tp[2];
try { verifyJwt(forged, secret); } catch (e) { console.log('篡改 payload:', e.message); }

const noneToken = b64url({ alg: 'none', typ: 'JWT' }) + '.' + tp[1] + '.';
try { verifyJwt(noneToken, secret); } catch (e) { console.log('alg=none 攻击:', e.message); }
